"""Pending waitqueue lessons. Both source files read; full authoring remains open."""
ROWS = [
('Waitqueue 구조·대기자와 대기열의 역할', 'include/linux/wait.h', 'wait_queue_entry',
 '대기자 한 명을 표현하는 wait_queue_entry에는 flags, private, func, 이중 연결 리스트의 entry가 있습니다. private는 기본 사용에서 task를 가리키지만 사용자 콜백은 다른 문맥을 사용할 수도 있습니다. func는 깨움 요청을 처리하는 함수 포인터입니다. wait_queue_head는 리스트 head와 이를 보호하는 spinlock을 가집니다. 객체의 자료구조와 실제 task의 실행 상태를 구분하세요.',
 '여러 task가 같은 조건을 기다릴 때 대기열을 사용합니다. 기본 콜백이 private를 task로 해석하는 규약을 지키세요. 사용자 콜백으로 교체할 때는 private의 해석, 반환값, 리스트 등록과 해제 책임을 함께 정합니다.',
 [('wait_queue_entry의 func는 무엇인가요?', '깨움 요청을 처리하는 함수 포인터입니다.', '항상 task 번호를 저장하는 정수입니다.', 'typedef는 대기 항목, mode, flags, key를 받는 함수 포인터입니다. 콜백 호출로 여러 종류의 깨움을 같은 대기열에 연결합니다.'),
  ('private가 항상 task 포인터라는 사실을 구조체 타입이 강제하나요?', '아닙니다. void 포인터이며 콜백 규약에 따라 해석합니다.', '맞습니다. struct task_struct 포인터 타입입니다.', '원문의 타입은 void *입니다. 기본 콜백의 사용 계약과 구조체가 표현할 수 있는 범위를 구별해야 합니다.')]),
('Waitqueue 초기화·리스트 연결 전후의 차이', 'include/linux/wait.h', '__WAITQUEUE_INITIALIZER',
 'DECLARE_WAITQUEUE는 지정 task와 default_wake_function을 넣고 entry의 두 링크를 NULL로 초기화합니다. 반면 DEFINE_WAIT_FUNC와 init_wait는 자신의 entry를 가리키는 빈 리스트를 만들며 autoremove 계열 콜백을 사용할 수 있습니다. init_waitqueue_entry는 flags, private, func만 설정하고 리스트 링크를 초기화하지 않습니다. 같은 초기화라는 이름이어도 이후 등록 함수가 기대하는 링크 상태가 다릅니다.',
 'prepare 계열이 list_empty로 등록 여부를 검사하는 경우에는 자기 참조 리스트 초기화가 필요합니다. init_waitqueue_entry만 호출한 뒤 초기화되지 않은 링크를 조회하지 마세요. 정적 선언과 실행 중 초기화가 각각 어떤 필드를 설정하는지 확인합니다.',
 [('init_waitqueue_entry가 entry 링크까지 초기화하나요?', '아닙니다. flags, private, func만 설정합니다.', '맞습니다. 모든 필드를 자기 참조로 만듭니다.', '원문 함수에는 INIT_LIST_HEAD 호출이 없습니다. 함수 이름만 보고 리스트 상태까지 준비되었다고 가정하면 안 됩니다.'),
  ('DECLARE_WAITQUEUE와 DEFINE_WAIT_FUNC의 entry 초기값은 같은가요?', '아닙니다. NULL 링크와 자기 참조 링크로 다릅니다.', '맞습니다. 둘 다 NULL입니다.', '각 매크로의 지정 초기화를 읽으면 차이를 확인할 수 있습니다. 준비 함수의 list_empty 계약과 연결해서 읽어야 합니다.')]),
('Waitqueue head 초기화·잠금과 lockdep 클래스', 'kernel/sched/wait.c', '__init_waitqueue_head',
 '__init_waitqueue_head는 spinlock을 초기화하고 lockdep의 클래스와 이름을 연결한 뒤 리스트 head를 자기 참조로 만듭니다. 헤더의 init_waitqueue_head 매크로는 호출 지점의 정적 lock_class_key를 전달합니다. 정적 DECLARE_WAIT_QUEUE_HEAD는 잠금과 리스트의 정적 초기화를 제공합니다. CONFIG_LOCKDEP의 ONSTACK 선언은 실행 중 초기화 경로를 사용합니다.',
 '새 대기열은 등록이나 깨움 전에 초기화하세요. 사용 중인 대기열을 재초기화하여 연결을 잃지 않게 합니다. 스택에 만든 대기열은 기다리는 task와 관련 콜백이 더 이상 접근하지 않을 때까지 살아 있어야 합니다.',
 [('대기열 head의 빈 리스트는 어떻게 표현하나요?', 'head의 링크가 자기 자신을 가리킵니다.', 'head를 반드시 NULL로 둡니다.', 'INIT_LIST_HEAD는 이중 연결 리스트의 센티널을 자기 참조로 초기화합니다. 빈 대기열도 유효한 리스트 head를 유지합니다.'),
  ('사용 중인 head를 다시 초기화해도 등록된 대기자가 보존되나요?', '아닙니다. 기존 연결을 잃을 수 있습니다.', '맞습니다. 자동으로 모든 항목을 옮깁니다.', '초기화 함수는 기존 리스트를 순회하거나 옮기지 않습니다. 객체 초기화와 사용 중 상태 변경은 구별해야 합니다.')]),
('Waitqueue active·잠금 없는 관측과 놓친 깨움', 'include/linux/wait.h', 'waitqueue_active',
 'waitqueue_active는 리스트가 비었는지 조회할 뿐 잠금을 잡지 않습니다. waker가 조건을 true로 바꾼 뒤 이 조회로 wake 호출을 생략하려면 원문이 요구하는 메모리 배리어 또는 대기열 잠금 규약을 지켜야 합니다. 그렇지 않으면 waker는 빈 리스트를 보고 waiter는 이전 조건을 보아 서로의 변경을 놓칠 수 있습니다. 관측 결과가 task 소유권이나 객체 수명까지 보장하지는 않습니다.',
 '헤더의 CPU0·CPU1 순서도를 따라 조건 변경, smp_mb, 리스트 관측, prepare와 조건 재검사의 순서를 적어 보세요. 단순 최적화라고 배리어를 제거하지 마세요. 반환값은 그 순간의 리스트 관측으로 해석합니다.',
 [('waitqueue_active 자체가 대기열 spinlock을 잡나요?', '아닙니다. 리스트 상태만 조회합니다.', '맞습니다. 내부에서 IRQ까지 저장합니다.', '함수 본문은 !list_empty를 반환합니다. 잠금이나 메모리 순서의 필요 조건은 호출자 프로토콜에 있습니다.'),
  ('조건을 바꾼 뒤 잠금 없는 active 검사 전에 배리어를 생략해도 항상 안전한가요?', '아닙니다. 서로의 변경을 놓칠 수 있습니다.', '맞습니다. 리스트 조회가 모든 순서를 보장합니다.', '원문 주석은 조건 저장보다 리스트 읽기가 앞서 관측될 위험을 설명합니다. 양쪽의 메모리 순서 규약이 필요합니다.')]),
('Waitqueue sleeper 조회·단일 항목과 배리어 포함 검사', 'include/linux/wait.h', 'wq_has_sleeper',
 'wq_has_single_sleeper는 list_is_singular로 리스트에 항목이 하나인지 검사합니다. 이 이름만으로 그 task가 현재 잠들어 있다고 증명할 수는 없습니다. wq_has_sleeper는 smp_mb를 실행한 뒤 waitqueue_active를 호출합니다. 이 배리어는 기다리는 쪽의 배리어와 짝을 이루며, 단순 리스트 수 조회와 메모리 순서 보조를 구별해야 합니다.',
 '단일 항목 검사는 active 주석의 사용 조건을 함께 따르세요. wq_has_sleeper를 사용하더라도 객체 수명, 리스트 변경 직렬화, 조건 변경과의 전체 프로토콜을 지켜야 합니다. 항목 수를 실제 sleeping task 수로 단정하지 마세요.',
 [('wq_has_sleeper가 active 검사 전에 수행하는 것은 무엇인가요?', 'smp_mb 메모리 배리어입니다.', '모든 대기자를 강제로 깨우는 동작입니다.', '함수는 배리어 뒤에 리스트 존재 여부를 조회합니다. 조회와 깨움은 별개 역할입니다.'),
  ('single_sleeper 조회가 잠금 소유권을 전달하나요?', '아닙니다. 리스트 항목 수를 관측합니다.', '맞습니다. 반환 true가 spinlock 획득입니다.', '본문은 list_is_singular 검사입니다. 반환값은 잠금 획득이나 등록된 task의 현재 실행 상태를 증명하지 않습니다.')]),
('Waitqueue 등록 순서·priority 앞부분과 일반 항목', 'include/linux/wait.h', '__add_wait_queue',
 '__add_wait_queue는 리스트 처음부터 WQ_FLAG_PRIORITY 항목이 연속하는 구간을 지나갑니다. 이후 그 위치에 새 항목을 삽입하여 기존 priority 앞부분을 유지합니다. priority가 없는 일반 항목은 그 뒤의 앞쪽에 들어가므로 일반 항목 전체가 FIFO가 되는 것은 아닙니다. 이 내부 helper는 대기열 잠금을 스스로 잡지 않습니다.',
 '일반 등록은 add_wait_queue 같은 잠금 포함 API로 수행하세요. 내부 helper를 직접 사용할 때는 head 잠금이 이미 보호하는 문맥이어야 합니다. priority 순서와 일반 항목 순서, exclusive 예산을 각각 구분합니다.',
 [('일반 항목 등록은 항상 리스트 맨 뒤에 들어가나요?', '아닙니다. priority 앞부분 바로 뒤에 들어갑니다.', '맞습니다. 모든 항목은 FIFO입니다.', 'helper는 priority 항목을 지난 위치에 list_add를 사용합니다. tail 등록 helper와 동작이 다릅니다.'),
  ('__add_wait_queue가 내부에서 잠금을 획득하나요?', '아닙니다. 호출자가 보호해야 합니다.', '맞습니다. 함수 이름의 밑줄이 잠금을 뜻합니다.', '본문은 리스트 순회와 삽입입니다. 외부 add_wait_queue가 IRQ 저장과 잠금으로 이 작업을 보호합니다.')]),
('Waitqueue exclusive·플래그와 tail 등록', 'kernel/sched/wait.c', 'add_wait_queue_exclusive',
 'add_wait_queue_exclusive는 EXCLUSIVE 플래그를 설정하고 IRQ 상태를 저장하며 head 잠금을 잡은 뒤 tail에 삽입합니다. 일반 add_wait_queue는 EXCLUSIVE를 지우고 priority 뒤의 앞쪽에 삽입합니다. add_wait_queue_priority는 EXCLUSIVE와 PRIORITY를 함께 설정하고 앞쪽 priority 구간에 넣습니다. exclusive는 깨움 예산의 소비 규칙이며, 조건 데이터의 상호 배제 잠금은 아닙니다.',
 '한 번의 사건으로 일부 대기자만 처리하게 하려면 exclusive 규칙과 실제 조건 소비를 함께 설계합니다. flag 이름만으로 공유 데이터가 보호된다고 가정하지 마세요. 이미 등록된 같은 항목을 중복으로 삽입하지 않습니다.',
 [('add_wait_queue_exclusive는 어느 쪽에 삽입하나요?', '리스트 맨 뒤에 삽입합니다.', '항상 모든 priority 항목보다 앞에 삽입합니다.', '이 API는 __add_wait_queue_entry_tail을 사용합니다. 일반 등록이나 priority 등록과의 차이를 확인하세요.'),
  ('EXCLUSIVE 플래그가 공유 조건 데이터의 mutex 역할을 하나요?', '아닙니다. 깨움 순회의 예산 규칙입니다.', '맞습니다. 조건 쓰기를 자동으로 직렬화합니다.', 'flag는 콜백이 성공했을 때 깨움 예산을 소비할지 결정합니다. 실제 데이터 보호는 호출자 잠금 규약에 있습니다.')]),
('Waitqueue 깨움 순회·콜백 결과와 exclusive 예산', 'kernel/sched/wait.c', '__wake_up_common',
 '깨움 핵심 함수는 잠금이 잡혀 있음을 검사하고 항목을 안전 순회합니다. 각 항목의 플래그를 콜백 호출 전에 저장합니다. 콜백이 음수를 반환하면 순회를 멈추고, 0이면 예산을 소비하지 않습니다. 양수를 반환한 exclusive 항목은 예산을 하나 줄이며 0에 도달하면 끝냅니다. 일반 항목 성공은 exclusive 예산을 줄이지 않습니다. 콜백이 자신을 리스트에서 제거할 수 있어 next를 미리 보존합니다.',
 '사용자 콜백은 음수·0·양수의 의미를 깨움 순회 계약에 맞춰 정하세요. 깨움 예산 1을 모든 task 중 정확히 한 명만 호출한다는 뜻으로 해석하지 마세요. 앞선 일반 항목이나 priority 항목에 따라 순회 범위가 달라집니다.',
 [('일반 항목의 콜백 성공도 exclusive 예산을 줄이나요?', '아닙니다. EXCLUSIVE 항목 성공만 줄입니다.', '맞습니다. 모든 양수 반환이 예산을 줄입니다.', '본문은 ret와 flags의 EXCLUSIVE를 함께 검사합니다. 비 exclusive 항목의 성공은 예산을 소비하지 않습니다.'),
  ('콜백이 0을 반환하면 예산 1의 순회가 즉시 끝나나요?', '아닙니다. 다음 항목을 계속 검사합니다.', '맞습니다. 호출 한 번이 예산 하나입니다.', '실제로 깨우지 못한 콜백은 예산을 소비하지 않습니다. 호출 횟수와 성공한 exclusive 깨움 수는 다릅니다.')]),
('Waitqueue wake 반환·전체 호출 수와 exclusive 성공 수', 'kernel/sched/wait.c', '__wake_up_common_lock',
 '잠금 포함 깨움 함수는 IRQ 상태를 저장하고 head 잠금을 잡은 뒤 핵심 순회를 수행합니다. 원래 exclusive 예산에서 남은 예산을 빼 반환합니다. 따라서 반환값은 성공한 exclusive 항목 수이며 일반 항목 성공 수나 콜백 호출 횟수는 아닙니다. wake_up_all은 예산 0으로 시작해 양수 예산의 종료 조건을 사용하지 않고 순회하지만, 사용자 콜백의 음수 반환은 여전히 순회를 멈출 수 있습니다.',
 '깨움 반환값을 대기열 길이나 전체 성공 수로 사용하지 마세요. wake_up_all의 모두라는 이름도 사용자 콜백의 중단 계약을 없애지는 않습니다. 깨움 함수가 반환한 뒤 조건이나 자원의 실제 소비는 각 task가 다시 확인해야 합니다.',
 [('일반 항목만 성공적으로 깨워도 __wake_up 반환값이 0일 수 있나요?', '그렇습니다. exclusive 성공 수를 반환합니다.', '아닙니다. 전체 성공 수를 반환합니다.', '잠금 wrapper는 nr_exclusive에서 remaining을 뺍니다. 일반 항목은 해당 예산을 줄이지 않습니다.'),
  ('wake_up_all에서 음수 콜백 반환도 무시하고 끝까지 순회하나요?', '아닙니다. 음수 반환이면 중단합니다.', '맞습니다. all은 모든 중단 조건을 없앱니다.', 'nr_exclusive가 0이어도 ret < 0 분기는 그대로 있습니다. 예산 규칙과 콜백의 순회 중단 규칙은 별개입니다.')]),
('Waitqueue prepare·등록 뒤 대기 상태 설정', 'kernel/sched/wait.c', 'prepare_to_wait',
 'prepare_to_wait는 EXCLUSIVE를 지우고 잠금 구간에서 아직 등록되지 않은 항목을 넣은 뒤 set_current_state로 대기 상태를 설정합니다. 등록 뒤 상태 설정의 배리어는 잠금 없는 깨움 존재 검사와 조건 재검사를 연결합니다. spin_unlock만으로 이후 조건 읽기까지 필요한 모든 순서가 보장되는 것은 아니라는 점을 원문 주석이 설명합니다. 이미 등록된 항목은 다시 삽입하지 않습니다.',
 '일반적인 직접 대기 반복문은 prepare, 조건 검사, 필요할 때 schedule, 종료 후 finish 순서를 지킵니다. 조건을 먼저 한 번 검사한 뒤 등록 없이 잠들면 깨움을 놓칠 수 있습니다. prepare가 등록 여부를 읽을 수 있도록 항목의 링크를 초기화하세요.',
 [('prepare는 등록과 state 설정 중 무엇을 먼저 하나요?', '대기열 등록을 먼저 합니다.', '항상 state를 먼저 바꾸고 등록합니다.', '본문은 잠금 구간에서 등록 여부를 검사하고 삽입한 뒤 set_current_state를 호출합니다. 원문 주석의 순서 전제와 연결됩니다.'),
  ('이미 등록된 항목은 반복 prepare 때 다시 삽입하나요?', '아닙니다. list_empty일 때만 삽입합니다.', '맞습니다. 같은 항목을 매번 추가합니다.', '등록 여부 검사로 중복 삽입을 피합니다. 항목 링크를 올바르게 초기화하고 정리해야 이 검사가 의미를 가집니다.')]),
('Waitqueue exclusive prepare·첫 대기자 반환의 한계', 'kernel/sched/wait.c', 'prepare_to_wait_exclusive',
 'exclusive prepare는 EXCLUSIVE를 설정하고, 아직 연결되지 않은 항목을 tail에 넣습니다. 새로 등록할 때 head가 비어 있었으면 was_empty를 true로 반환합니다. 이미 등록된 항목이면 이 지역 변수는 초기값 false로 남습니다. 따라서 반환값은 자신이 현재 유일한 대기자인지 일반적으로 알려 주는 조회 함수가 아닙니다. 대기 상태 설정은 등록 뒤 잠금 구간에서 수행합니다.',
 '반환값을 새 등록 당시의 빈 대기열 여부로 사용하세요. 같은 항목으로 반복 호출했을 때 false가 나와도 다른 대기자가 반드시 있다는 뜻은 아닙니다. 현재 리스트의 단일 항목 조회와 등록 동작의 결과를 구분합니다.',
 [('항목이 이미 유일하게 등록되어 있으면 재호출 반환은 반드시 true인가요?', '아닙니다. 새 삽입을 하지 않으면 false입니다.', '맞습니다. 유일한 대기자는 언제나 true입니다.', 'was_empty는 새 삽입 분기에서만 갱신됩니다. 현재 항목 수의 일반 조회가 아니라 등록 경로의 결과입니다.'),
  ('새 exclusive 항목은 어디에 등록되나요?', '리스트 맨 뒤입니다.', '항상 priority 항목의 앞입니다.', '함수는 __add_wait_queue_entry_tail을 사용합니다. 플래그와 등록 위치를 따로 확인하세요.')]),
('Waitqueue signal 준비·제거와 -ERESTARTSYS', 'kernel/sched/wait.c', 'prepare_to_wait_event',
 'prepare_to_wait_event는 잠금 아래 signal_pending_state를 검사합니다. 허용된 signal이 있으면 list_del_init으로 항목을 제거하고 -ERESTARTSYS를 반환합니다. 그렇지 않으면 flag에 따라 앞쪽 또는 tail에 등록하고 대기 상태를 설정합니다. 공통 대기 매크로는 이 반환 뒤 조건을 먼저 재검사합니다. 이미 깨움이 선택한 exclusive waiter가 충족된 조건을 성공으로 소비할 기회를 주는 순서입니다.',
 'signal 반환을 즉시 조건 실패로 단정하지 말고 공통 매크로의 조건 우선 판정과 연결하세요. rcuwait의 -EINTR과 이 일반 waitqueue의 -ERESTARTSYS를 구별합니다. 직접 호출하면 제거된 항목과 task 상태의 정리 책임도 확인해야 합니다.',
 [('이 함수의 signal 경로 반환값은 무엇인가요?', '-ERESTARTSYS입니다.', '항상 rcuwait와 같은 -EINTR입니다.', '원문 일반 waitqueue 함수는 -ERESTARTSYS를 사용합니다. 서로 다른 대기 API의 오류 계약을 섞으면 안 됩니다.'),
  ('허용된 signal 경로에서 항목은 대기열에 남나요?', '아닙니다. list_del_init으로 제거합니다.', '맞습니다. 다음 wake가 제거할 때까지 남습니다.', 'signal 실패 경로는 이후 조건 변경과 wake가 다른 exclusive waiter를 선택할 수 있게 등록을 제거합니다.')]),
('Waitqueue 공통 macro·조건 우선과 오류 경로', 'include/linux/wait.h', '___wait_event',
 '공통 매크로는 스택의 대기 항목을 초기화하고 반복마다 prepare_to_wait_event를 호출합니다. 조건이 true이면 반복문을 끝내고 finish_wait를 호출합니다. 조건이 false이며 중단 가능한 state에서 준비 함수가 오류를 반환했다면 지역 label로 이동해 반환합니다. 이 signal 오류 경로는 finish_wait를 건너뜁니다. 준비 함수가 이미 항목을 제거한 계약과 함께 읽어야 하며, rcuwait의 공통 finish 경로와 동일하다고 가정하면 안 됩니다.',
 '지역 __ret의 명시적 shadow와 GNU statement expression을 확인하세요. 조건식은 여러 번 평가해도 안전하게 만듭니다. 모든 오류 경로에 finish가 있다는 추측 대신 goto label과 준비 함수의 정리를 직접 따라갑니다.',
 [('signal 오류 경로도 항상 finish_wait를 호출하나요?', '아닙니다. 지역 __out으로 이동합니다.', '맞습니다. 모든 경로가 finish를 거칩니다.', '오류 goto는 finish_wait 뒤의 label로 이동합니다. prepare_to_wait_event가 이미 항목을 제거하는 계약을 함께 읽어야 합니다.'),
  ('조건 성공과 signal 오류 중 무엇을 먼저 판정하나요?', '조건 성공입니다.', '항상 signal 오류입니다.', '매크로는 prepare의 반환을 받은 뒤 condition을 먼저 검사합니다. 조건이 false일 때만 오류 분기를 선택합니다.')]),
('Waitqueue finish·careful 조회와 조건부 제거', 'kernel/sched/wait.c', 'finish_wait',
 'finish_wait는 현재 task를 TASK_RUNNING으로 복구합니다. 그 뒤 list_empty_careful로 next와 prev를 함께 확인하고, 아직 연결된 것으로 보이면 잠금을 잡아 list_del_init으로 제거합니다. 잠금 밖 조회가 허용되는 이유는 원문이 명시한 리스트 변경자 잠금 규약과 careful 링크 검사에 있습니다. 임의의 모든 동시 리스트 삭제에 적용할 수 있는 일반 규칙은 아닙니다.',
 '직접 대기 반복문은 종료 후 finish_wait로 스택 대기 항목을 정리하세요. 일반 list_empty로 바꾸거나 다른 변경자가 잠금 규약을 따르지 않아도 된다고 가정하지 마세요. 항목의 메모리는 깨움 순회가 더 이상 접근하지 않을 때까지 유지합니다.',
 [('finish_wait의 첫 동작은 무엇인가요?', 'TASK_RUNNING 상태를 복구합니다.', 'task 메모리를 free합니다.', '함수는 __set_current_state를 먼저 호출합니다. 대기 종료의 상태 정리와 객체 메모리 해제는 다른 동작입니다.'),
  ('잠금 밖에서 사용하는 빈 리스트 검사는 무엇인가요?', 'list_empty_careful입니다.', 'next 하나만 읽는 임의 검사입니다.', '원문은 next와 prev의 careful 검사와 다른 변경자의 잠금 규약을 조건으로 설명합니다. 해당 전제를 제거해서는 안 됩니다.')]),
('Waitqueue autoremove·깨움 성공 때만 링크 정리', 'kernel/sched/wait.c', 'autoremove_wake_function',
 'autoremove_wake_function은 default_wake_function을 호출하고 결과가 0이 아닐 때 list_del_init_careful로 자기 항목을 제거합니다. 실제로 깨우지 못했으면 등록이 유지됩니다. 이 careful 삭제는 finish_wait의 careful 조회와 연결되는 계약입니다. 기본 깨움 함수 자체가 모든 콜백의 private 타입이나 대기 조건을 해석하는 것은 아닙니다.',
 'DEFINE_WAIT의 기본 autoremove 동작과 등록 유지 조건을 확인하세요. 콜백이 실행되었다는 사실만으로 항목이 제거되었다고 가정하지 마세요. wait loop는 깨움 뒤에도 실제 조건을 다시 검사합니다.',
 [('기본 깨움이 0을 반환하면 항목을 제거하나요?', '아닙니다. 등록을 유지합니다.', '맞습니다. 콜백 호출만으로 제거합니다.', '삭제는 if (ret) 분기 안에 있습니다. 콜백 호출, 깨움 성공, 항목 제거는 서로 구분해야 합니다.'),
  ('성공한 autoremove는 어떤 삭제 helper를 쓰나요?', 'list_del_init_careful입니다.', '메모리 free만 호출합니다.', '이 함수는 링크를 careful 방식으로 제거하고 빈 항목 상태를 복구합니다. 항목의 메모리를 직접 해제하지는 않습니다.')])
]

ROWS.extend([
('Waitqueue wake 종류·state 필터와 호출자 잠금', 'include/linux/wait.h', 'wake_up',
 'wake_up은 TASK_NORMAL과 exclusive 예산 1을 전달합니다. wake_up_interruptible은 TASK_INTERRUPTIBLE을 전달하며, _nr는 지정 예산을, _all은 예산 0을 전달합니다. _locked 변형은 호출자가 이미 head 잠금을 잡은 상태에서 내부 순회를 호출합니다. 이름이 비슷해도 task 상태 필터, 예산, 잠금 책임의 세 가지 축이 다릅니다.',
 '어떤 state로 기다리는 task를 깨우려는지 먼저 정합니다. head 잠금 안에서는 잠금을 다시 획득하는 일반 wake 대신 계약에 맞는 locked 변형을 선택하세요. 예산은 성공한 exclusive 항목 수를 제한한다는 점을 기억합니다.',
 [('wake_up_interruptible이 전달하는 state 필터는 무엇인가요?', 'TASK_INTERRUPTIBLE입니다.', '항상 TASK_NORMAL 전체입니다.', '헤더 매크로의 인자를 직접 확인하면 차이가 보입니다. task가 대기하는 state와 깨움 mode를 연결해야 합니다.'),
  ('wake_up_locked는 호출자가 head 잠금을 잡아야 하나요?', '그렇습니다.', '아닙니다. 언제나 내부에서 잠금을 잡습니다.', 'locked API는 head 잠금이 이미 유지되는 문맥을 위해 내부 순회를 호출합니다. 일반 잠금 포함 API와 혼용하면 안 됩니다.')]),
('Waitqueue sync wake·스케줄링 힌트와 완료 대기의 차이', 'kernel/sched/wait.c', '__wake_up_sync_key',
 'sync wake는 깨우는 쪽이 곧 schedule할 것이라는 정보를 WF_SYNC로 전달합니다. 원문 주석은 불필요한 CPU 이동이나 UP의 추가 선점을 줄이려는 목적을 설명합니다. 함수는 상대 task가 작업을 끝낼 때까지 기다리는 동기식 호출이 아닙니다. __wake_up_sync_key는 NULL head이면 바로 반환하고, 유효 head에는 예산 1과 key를 전달합니다. locked sync 변형의 잠금 책임도 호출자에게 있습니다.',
 'sync라는 이름을 작업 완료 보장이나 join으로 해석하지 마세요. 실제 scheduler 정책은 전달한 힌트를 사용하는 별도 코드에서 확인합니다. NULL 허용을 모든 wake API로 일반화하지 않습니다.',
 [('sync wake가 상대 task의 작업 완료까지 기다리나요?', '아닙니다. WF_SYNC 힌트를 전달합니다.', '맞습니다. 상대가 종료해야 반환합니다.', '원문은 깨우는 쪽이 곧 schedule할 상황의 최적화를 설명합니다. 호출의 완료와 깨워진 task의 작업 완료는 다른 시점입니다.'),
  ('__wake_up_sync_key에 NULL head를 주면 어떻게 하나요?', '검사 후 바로 반환합니다.', '반드시 NULL 잠금을 역참조합니다.', '이 함수에는 !wq_head 조기 반환이 있습니다. 다른 wake API도 같은 NULL 계약을 갖는다고 추측해서는 안 됩니다.')]),
('Waitqueue current CPU wake·WF_CURRENT_CPU 전달', 'kernel/sched/wait.c', '__wake_up_on_current_cpu',
 '__wake_up_on_current_cpu는 잠금 포함 공통 깨움에 예산 1, WF_CURRENT_CPU와 key를 전달합니다. 이 함수에서 직접 CPU 번호를 바꾸거나 대기열을 CPU별로 분리하지는 않습니다. 플래그가 실제 깨움 대상의 스케줄링에 미치는 효과는 기본 콜백과 scheduler의 후속 처리에서 정합니다. 따라서 이 helper만 읽고 모든 사용자 콜백이 반드시 현재 CPU에서 task를 실행시킨다고 단정할 수 없습니다.',
 '플래그 전달과 실제 CPU 배치의 결과를 구분하세요. 사용자 콜백이 wake_flags를 어떻게 해석하는지 함께 확인합니다. 대기열 잠금과 exclusive 예산은 이 변형에서도 공통 깨움 규칙을 따릅니다.',
 [('이 함수가 전달하는 wake flag는 무엇인가요?', 'WF_CURRENT_CPU입니다.', '항상 WF_SYNC만 전달합니다.', '원문 공통 호출의 네 번째 인자를 확인하세요. sync 변형과 current CPU 변형은 전달하는 플래그가 다릅니다.'),
  ('이 helper가 모든 사용자 콜백의 task CPU 배치를 직접 수행하나요?', '아닙니다. 후속 처리에 플래그를 전달합니다.', '맞습니다. 콜백과 무관하게 CPU를 바꿉니다.', '본문은 공통 깨움 호출입니다. 플래그 전달, 콜백의 해석, scheduler의 CPU 선택은 서로 다른 단계입니다.')]),
('Waitqueue poll key·이벤트 비트 전달과 포인터 해석', 'include/linux/wait.h', 'poll_to_key',
 'poll_to_key는 poll 이벤트 비트를 __poll_t와 uintptr_t를 거쳐 void 포인터 표현으로 전달합니다. key_to_poll은 이를 다시 이벤트 비트로 해석합니다. 이 key는 일반 객체 주소처럼 역참조하려고 만든 것이 아닙니다. poll wake 변형은 key를 콜백에 전달하고 normal 또는 interruptible mode, sync 또는 current CPU flag, 잠금 여부를 각각 선택합니다.',
 'poll 콜백은 key를 약속된 이벤트 마스크로 해석하세요. 일반 task 콜백의 private와 사건을 전달하는 key를 혼동하지 마세요. 사용자 주소라고 판단하여 key를 역참조하지 않습니다.',
 [('poll_to_key 결과를 일반 객체 주소처럼 역참조하나요?', '아닙니다. 이벤트 비트의 전달 표현입니다.', '맞습니다. 반드시 struct file 주소입니다.', '원문은 정수 폭 변환을 거쳐 마스크를 전달합니다. 포인터 타입으로 표현해도 실제 객체의 메모리 주소를 뜻하지는 않습니다.'),
  ('poll wake의 key와 항목의 private는 같은 역할인가요?', '아닙니다. 사건 정보와 콜백 문맥으로 구분합니다.', '맞습니다. 둘 다 항상 current입니다.', 'key는 깨움 호출마다 전달하는 사건 정보이며 private는 대기 항목에 저장한 문맥입니다. 콜백 계약에 따라 따로 해석합니다.')]),
('Waitqueue pollfree·통지 뒤 RCU 수명 정리', 'include/linux/wait.h', 'wake_up_pollfree',
 'pollfree는 task 수명에 묶인 드문 poll 대기열이 사라지기 전에 epoll 같은 사용자가 등록을 정리하도록 통지합니다. 내부 함수는 EPOLLHUP과 POLLFREE를 key로 전달하고, 콜백 처리 뒤 대기열이 비었는지 경고 검사합니다. 통지 함수 자체가 head를 해제하지 않습니다. 헤더는 호출자가 synchronize_rcu, call_rcu 또는 해당 allocator 규약으로 head 해제를 RCU 지연해야 한다고 명시합니다.',
 'poll 대기열의 수명이 file과 다른 경우 종료 절차를 설계할 때 사용하세요. 통지, 콜백의 등록 해제, RCU 수명 보장과 실제 메모리 해제를 순서대로 구분합니다. 경고가 없다는 사실만으로 모든 수명 규약을 지켰다고 판단하지 마세요.',
 [('wake_up_pollfree가 head 메모리를 직접 해제하나요?', '아닙니다. 사라질 대기열을 통지합니다.', '맞습니다. 통지 후 즉시 free합니다.', '헤더는 RCU 지연 해제를 별도의 호출자 책임으로 명시합니다. 통지와 메모리 해제는 다른 동작입니다.'),
  ('pollfree 통지 뒤 호출자가 고려해야 하는 수명 규칙은 무엇인가요?', 'head 해제를 RCU에 맞춰 지연해야 합니다.', '이벤트 비트만 지우면 즉시 해제해도 됩니다.', '잠금 없는 관측이나 마지막 등록 제거와 겹칠 수 있어 RCU 수명 보호가 필요합니다. 원문에 명시된 규약을 확인하세요.')]),
('Waitqueue locked wait·잠금을 풀고 잠든 뒤 재획득', 'kernel/sched/wait.c', 'do_wait_intr',
 'do_wait_intr는 head 잠금이 잡힌 상태에서 호출됩니다. 필요하면 tail에 등록하고 TASK_INTERRUPTIBLE 상태를 설정합니다. signal이 있으면 -ERESTARTSYS로 반환하며 잠금을 풀지 않습니다. 그렇지 않으면 잠금을 풀고 schedule한 뒤 다시 잠금을 잡아 반환합니다. IRQ 변형은 spin_unlock_irq와 spin_lock_irq를 사용합니다. locked 대기 매크로는 반복 종료 때 항목 제거와 TASK_RUNNING 복구를 수행합니다.',
 '조건을 head 잠금 아래 검사하고, 함수 밖의 잠금 방식과 IRQ 변형을 맞추세요. schedule 중에는 해당 잠금이 풀려 있다는 점을 고려합니다. 호출 전후 잠금 보유와 대기 중 잠금 해제를 구별하세요.',
 [('정상 schedule 경로는 head 잠금을 보유한 채 잠드나요?', '아닙니다. 풀고 잠든 뒤 다시 획득합니다.', '맞습니다. spinlock을 계속 보유합니다.', '본문은 spin_unlock, schedule, spin_lock 순서입니다. 대기 전후의 잠금 보유와 실제 잠든 구간의 상태는 다릅니다.'),
  ('초기 signal 오류 경로에서 head 잠금을 풀고 반환하나요?', '아닙니다. 잠금은 유지됩니다.', '맞습니다. 항상 unlock 뒤 오류를 반환합니다.', 'signal 검사와 반환은 unlock보다 앞에 있습니다. 상위 locked 매크로는 잠금이 유지되는 계약으로 정리합니다.')]),
('Waitqueue wait_woken·깨움 플래그와 정지 요청', 'kernel/sched/wait.c', 'wait_woken',
 'wait_woken은 지정 대기 상태를 설정한 뒤 WQ_FLAG_WOKEN이 없고 kthread 정지나 park 요청도 없을 때만 schedule_timeout합니다. 그 뒤 TASK_RUNNING을 복구하고 smp_store_mb로 WOKEN 비트를 지웁니다. 반환값은 남은 timeout입니다. 이 함수가 조건 자체를 검사하거나 항목을 등록·제거하는 것은 아니므로 호출자는 별도의 조건 반복문과 대기열 수명 관리를 유지해야 합니다.',
 'DEFINE_WAIT_FUNC와 woken_wake_function을 사용할 때 원문 예제의 add, 조건 반복문, wait_woken, remove 순서를 따르세요. WOKEN을 단순 조건 성공으로 취급하지 마세요. 정지 요청 때문에 실제 schedule을 건너뛸 수 있습니다.',
 [('WOKEN이 이미 있으면 반드시 schedule_timeout을 호출하나요?', '아닙니다. 호출을 건너뜁니다.', '맞습니다. 플래그와 관계없이 항상 잠듭니다.', '조건은 WOKEN이 없고 정지·park 요청도 없는 경우에만 대기합니다. 깨움 관측과 종료 요청을 함께 처리합니다.'),
  ('wait_woken이 대기 항목의 등록과 제거도 모두 하나요?', '아닙니다. 호출자의 별도 책임입니다.', '맞습니다. 매 호출이 add와 remove를 수행합니다.', '함수 본문은 task 상태, WOKEN, timeout을 다룹니다. 원문 사용 예제는 반복문 바깥에서 별도로 등록과 제거를 수행합니다.')]),
('Waitqueue woken 콜백·배리어 A·B·C의 연결', 'kernel/sched/wait.c', 'woken_wake_function',
 'woken 콜백은 메모리 배리어 C 뒤 WQ_FLAG_WOKEN을 설정하고 기본 깨움 함수를 호출합니다. wait_woken의 대기 상태 설정 A는 기본 깨움의 full barrier와 연결되며, WOKEN을 지우는 store 배리어 B는 콜백의 C와 연결됩니다. 원문은 task 상태와 깨움 비트의 관측이 모두 사라지는 문제를 피하려는 순서를 설명합니다. 직렬 코드의 출력만으로 이 약한 메모리 순서 프로토콜 전체를 증명할 수는 없습니다.',
 'WOKEN 비트 설정을 기본 깨움 성공 후로 임의 이동하지 마세요. 이 콜백은 autoremove와 달리 항목을 스스로 제거하지 않습니다. 기본 함수가 0을 반환하는 경우에도 WOKEN 설정은 이미 수행된다는 점을 확인합니다.',
 [('기본 깨움이 0이면 WOKEN 설정도 취소되나요?', '아닙니다. 비트는 호출 전에 설정됩니다.', '맞습니다. 성공 때만 비트를 설정합니다.', '콜백 본문은 배리어와 WOKEN 설정 뒤 default_wake_function을 호출합니다. 플래그 관측과 실제 task 깨움 결과를 구분하세요.'),
  ('woken_wake_function은 항목을 자동으로 리스트에서 제거하나요?', '아닙니다. 별도 제거가 필요합니다.', '맞습니다. autoremove와 같은 삭제를 합니다.', '이 함수에는 리스트 삭제 호출이 없습니다. 비슷한 깨움 콜백이라도 항목 정리 계약은 서로 다릅니다.')])
])

ROWS.extend([
('Waitqueue 일반 wait_event·조건과 void 반환', 'include/linux/wait.h', 'wait_event',
 'wait_event는 might_sleep로 잠들 수 있는 문맥인지 확인한 뒤 조건을 먼저 검사합니다. 이미 true이면 대기 등록 없이 끝납니다. false이면 공통 대기 매크로를 TASK_UNINTERRUPTIBLE, 비 exclusive, 초기 반환값 0과 schedule 명령으로 실행합니다. 바깥 매크로는 do-while 문이고 성공 코드를 반환하는 표현식이 아닙니다. 호출자는 조건을 바꿀 수 있는 변수 변경 뒤 wake를 수행해야 합니다.',
 '잠들 수 있는 task 문맥에서 사용하고 spinlock 보유 상태나 IRQ 문맥에서 임의 호출하지 마세요. 결과 코드 대입보다 반환 뒤 실제 조건과 필요한 자원 소비를 수행합니다. 조건은 등록 전후와 깨움 뒤 반복 검사될 수 있습니다.',
 [('일반 wait_event를 항상 int 결과 대입식으로 쓰나요?', '아닙니다. 바깥 매크로는 do-while 문입니다.', '맞습니다. 모든 대기 함수는 int 표현식입니다.', '이 매크로의 문법과 반환 계약을 직접 확인해야 합니다. interruptible 표현식 매크로와 일반 wait_event의 사용 방식은 다릅니다.'),
  ('초기 조건이 true여도 반드시 대기열에 등록하나요?', '아닙니다. 바로 끝낼 수 있습니다.', '맞습니다. 조건과 관계없이 prepare를 호출합니다.', '바깥 조건 검사에서 break하면 내부 대기 매크로를 실행하지 않습니다. 조건 충족과 실제 수면은 구별해야 합니다.')]),
('Waitqueue interruptible·signal 오류와 반복 조건', 'include/linux/wait.h', 'wait_event_interruptible',
 'interruptible 대기는 TASK_INTERRUPTIBLE을 사용하며 조건 성공에 0, 허용된 signal에 -ERESTARTSYS를 반환합니다. 바깥 조건 검사에서 이미 true이면 내부 대기를 하지 않습니다. 내부에서는 준비 함수의 signal 결과를 받은 뒤에도 조건을 먼저 검사합니다. 따라서 조건과 signal을 함께 관측했을 때 조건 성공을 판정할 수 있습니다. 모든 signal이 모든 대기 state를 깨우는 것은 아닙니다.',
 '반환값을 확인하고 오류를 상위 호출 계약에 맞게 처리하세요. 일반 대기열 오류를 사용자 공간 errno로 그대로 이해하기보다 syscall의 재시작 처리와 연결합니다. C 조건식의 부작용이 반복 실행되지 않도록 주의합니다.',
 [('interruptible 대기의 조건 성공 반환값은 무엇인가요?', '0입니다.', '항상 남은 시간의 양수입니다.', '이 변형에는 timeout 인자가 없습니다. 성공 코드 0과 시간 제한 대기의 잔여 시간 계약을 섞지 마세요.'),
  ('이 API의 signal 중단 코드는 무엇인가요?', '-ERESTARTSYS입니다.', '언제나 -ETIME입니다.', '일반 대기열의 signal 준비 함수와 공통 매크로가 -ERESTARTSYS를 전달합니다. -ETIME은 고해상도 시간 만료 계약에 등장합니다.')]),
('Waitqueue timeout·jiffies 잔여값과 만료 경계', 'include/linux/wait.h', 'wait_event_timeout',
 'wait_event_timeout은 timeout을 long __ret로 보관하고 ___wait_cond_timeout으로 조건을 감쌉니다. 조건이 false이고 시간이 만료되면 0, 만료 경계에서 조건이 true이면 1, 만료 전에 성공하면 최소 1인 잔여 jiffies를 반환합니다. 실제 대기에서는 schedule_timeout의 남은 시간을 계속 저장합니다. 반환 1은 경계 성공과 잔여 한 jiffy 성공을 모두 표현할 수 있습니다.',
 'timeout 단위가 밀리초라고 가정하지 말고 jiffies 변환 규약을 확인하세요. 0과 양수를 구분하며, 반환 1만으로 정확한 경과 시간을 계산하지 않습니다. 조건 변경 뒤 wake 규약은 시간 제한 대기에도 적용됩니다.',
 [('만료 경계에서 조건이 true이면 어떤 값을 반환하나요?', '성공을 구별하는 1입니다.', '항상 만료를 뜻하는 0입니다.', '조건 helper는 조건이 true이고 __ret가 0이면 1로 조정합니다. 마지막 조건 재검사가 성공과 만료를 구별합니다.'),
  ('timeout의 단위는 무엇인가요?', 'jiffies입니다.', '항상 마이크로초입니다.', '원문 문서는 timeout을 jiffies로 명시합니다. 숫자만 보고 시간 단위를 정하면 실제 대기 시간이 달라집니다.')]),
('Waitqueue interruptible timeout·세 가지 반환 영역', 'include/linux/wait.h', 'wait_event_interruptible_timeout',
 'interruptible timeout은 TASK_INTERRUPTIBLE, 조건 timeout helper와 schedule_timeout을 조합합니다. 조건 성공은 양수 잔여값 또는 경계 성공의 1, 조건 미충족 만료는 0, signal 중단은 -ERESTARTSYS입니다. 반환값이 long인 이유는 잔여 시간 값을 담기 위해서입니다. 조건 우선 판정과 signal 경로의 등록 제거는 일반 공통 대기와 같은 계약을 따릅니다.',
 'ret > 0, ret == 0, ret < 0을 나누어 처리하세요. 단순 if(ret)만 사용하면 음수 오류도 성공처럼 처리할 수 있습니다. 상위 데이터의 보호 잠금과 시간 제한 대기의 상태 전환을 별도로 확인합니다.',
 [('if(ret)만으로 조건 성공을 판정해도 충분한가요?', '아닙니다. 음수 signal 오류도 참으로 평가됩니다.', '맞습니다. 모든 0이 아닌 값은 성공입니다.', '이 API는 양수 성공, 0 만료, 음수 오류를 사용합니다. C의 참·거짓 평가와 API 반환 계약을 구분해야 합니다.'),
  ('시간 제한 대기의 반환 지역 변수는 왜 long인가요?', '잔여 timeout 값을 표현하기 위해서입니다.', '항상 task 포인터를 저장하기 위해서입니다.', '헤더는 timeout 값을 반환할 수 있는 변형에 long을 사용한다고 설명합니다. 일반 int 성공 코드 변형과 차이가 있습니다.')]),
('Waitqueue I/O wait·대기 명령 교체', 'include/linux/wait.h', 'io_wait_event',
 'io_wait_event는 일반 wait_event와 같은 초기 조건 검사와 TASK_UNINTERRUPTIBLE 대기 구조를 사용하지만 공통 매크로의 명령을 io_schedule로 바꿉니다. 조건을 자동으로 디스크 완료 조건으로 해석하는 함수는 아닙니다. I/O 대기와 관련된 스케줄러 처리는 io_schedule의 별도 구현에서 담당합니다. 이 wrapper 자체에는 timeout이나 signal 오류 반환을 추가하는 코드가 없습니다.',
 'I/O 대기를 표현하려는 문맥에서 후속 io_schedule 계약과 함께 사용합니다. 조건식과 깨움 책임은 여전히 호출자에게 있습니다. 함수 이름만으로 특정 장치 작업이 시작되거나 자동 완료된다고 가정하지 마세요.',
 [('일반 대기와 비교해 교체되는 명령은 무엇인가요?', 'schedule 대신 io_schedule입니다.', '항상 memcpy 대신 read입니다.', '헤더의 __io_wait_event 인자를 보면 차이가 있습니다. 공통 대기 구조를 재사용하고 스케줄링 명령을 선택합니다.'),
  ('io_wait_event가 특정 디스크 작업을 직접 시작하나요?', '아닙니다. 호출자의 조건을 기다립니다.', '맞습니다. 모든 호출이 장치 요청을 만듭니다.', '매크로는 장치나 요청 인자를 받지 않습니다. I/O 요청 처리와 해당 조건의 대기를 다른 단계로 구별하세요.')]),
('Waitqueue freezable·freezer state와 signal 계약', 'include/linux/wait.h', 'wait_event_freezable',
 'freezable 대기는 TASK_INTERRUPTIBLE과 TASK_FREEZABLE을 함께 전달합니다. 조건 성공은 0이고 중단 가능한 signal은 일반 공통 경로의 오류를 전달합니다. timeout 변형은 같은 state에 잔여 시간 계약을 결합하며 exclusive 변형은 EXCLUSIVE를 추가합니다. TASK_FREEZABLE 비트의 실제 freezer 처리는 scheduler와 freezer의 후속 코드에 있으며 이 매크로가 별도의 freeze 반복문을 직접 구현하지는 않습니다.',
 'freezer 참여가 필요한 task의 대기 문맥에서 사용하고 signal 및 시간 제한 결과를 확인하세요. freezable을 데이터 불변성이나 메모리 해제 기능으로 해석하지 않습니다. state 비트 선택과 시스템 suspend 동작을 연결해서 읽습니다.',
 [('freezable wrapper는 어떤 state 비트를 함께 전달하나요?', 'TASK_INTERRUPTIBLE과 TASK_FREEZABLE입니다.', '항상 TASK_RUNNING만 전달합니다.', '헤더의 공통 매크로 인자를 직접 확인하면 두 비트의 결합을 볼 수 있습니다. freezer와 signal 처리를 별도 역할로 이해하세요.'),
  ('freezable이라는 이름이 공유 데이터를 불변으로 만든다는 뜻인가요?', '아닙니다. task 대기의 freezer 참여와 관련됩니다.', '맞습니다. 객체 쓰기를 모두 금지합니다.', '이 wrapper는 task 대기 state를 선택합니다. 공유 데이터 잠금이나 메모리 보호를 자동으로 제공하지 않습니다.')]),
('Waitqueue command·수면 전후 코드의 실행 조건', 'include/linux/wait.h', 'wait_event_cmd',
 'wait_event_cmd는 공통 매크로의 실제 대기 명령을 cmd1, schedule, cmd2 순서로 구성합니다. 따라서 초기 조건이 true이면 두 명령 모두 실행되지 않을 수 있고, 조건이 여러 번 false이면 수면 명령 구간마다 반복 실행됩니다. exclusive_cmd는 같은 순서에 exclusive 등록을 결합합니다. 함수 입장과 퇴장에 한 번씩 실행하는 보편적인 정리 구문으로 오해하면 안 됩니다.',
 'cmd1과 cmd2가 실제 잠드는 각 경로에서 반복 실행되어도 올바르게 짝을 이루도록 작성하세요. 이미 조건을 만족한 경로에서는 명령이 생략됩니다. 잠금 해제와 재획득을 넣을 경우 조건 검사와 상위 잠금 계약도 확인합니다.',
 [('초기 조건이 true여도 cmd1과 cmd2를 반드시 실행하나요?', '아닙니다. 내부 대기를 건너뛸 수 있습니다.', '맞습니다. 입장과 퇴장 때 한 번씩 실행합니다.', '바깥 매크로의 조건 break 뒤에는 공통 대기 호출이 없습니다. 명령은 실제 대기 반복문의 cmd에 포함됩니다.'),
  ('대기 반복이 여러 번이면 명령도 반복될 수 있나요?', '그렇습니다. 각 schedule 구간의 전후에 실행됩니다.', '아닙니다. 처음 값으로 자동 고정합니다.', '공통 반복문은 조건이 false일 때마다 cmd를 실행합니다. 명령의 부작용과 반복 가능성을 고려해야 합니다.')]),
('Waitqueue exclusive wrapper·깨움 선택과 조건 소비', 'include/linux/wait.h', 'wait_event_interruptible_exclusive',
 'interruptible_exclusive는 TASK_INTERRUPTIBLE에 exclusive 등록을 결합하고, killable_exclusive는 TASK_KILLABLE을, freezable_exclusive는 INTERRUPTIBLE과 FREEZABLE을 결합합니다. exclusive가 성공 반환값을 양수로 바꾸지는 않습니다. 일반 성공은 0이며 signal 처리는 state의 규약을 따릅니다. 깨움이 선택한 task가 실제 자원이나 조건을 소비하는 책임은 공유 상태를 보호하는 상위 프로토콜에 있습니다.',
 'exclusive를 한 task만 동시에 실행되는 mutex 보장으로 해석하지 마세요. 깨운 뒤 조건을 재검사하고 필요한 자원을 적절한 잠금 아래 소비합니다. state 차이에 맞는 signal 중단 계약을 확인합니다.',
 [('exclusive 대기의 일반 조건 성공이 반드시 양수인가요?', '아닙니다. timeout 없는 성공은 0입니다.', '맞습니다. EXCLUSIVE flag 값이 반환됩니다.', 'exclusive는 공통 매크로의 등록 플래그를 선택합니다. 초기 반환값 0을 해당 flag 값으로 교체하지 않습니다.'),
  ('exclusive wake 선택만으로 공유 자원의 소비가 직렬화되나요?', '아닙니다. 상위 상태 보호 규약이 필요합니다.', '맞습니다. task가 깨어나는 순간 mutex를 소유합니다.', '깨움 예산과 데이터 잠금은 서로 다른 역할입니다. 조건 성공 후 실제 자원을 소비할 때도 호출자 프로토콜을 지켜야 합니다.')]),
('Waitqueue TASK_IDLE·load와 일반 interruptible의 차이', 'include/linux/wait.h', 'wait_event_idle',
 'idle 대기는 TASK_IDLE을 선택하여 system load에 기여하지 않는 조건 대기를 표현합니다. idle_exclusive는 EXCLUSIVE 등록을 더하고, idle_timeout 계열은 잔여 jiffies 계약을 결합합니다. TASK_IDLE이라고 현재 task가 계속 실행되는 busy loop를 만드는 것은 아닙니다. 이 wrapper는 공통 대기에서 schedule을 호출하며 상태 비트 선택에 따라 signal 규약을 따릅니다.',
 'load 집계와 대기 state를 연결해서 읽으세요. idle이라는 이름을 임의 CPU idle 진입이나 signal 중단 가능성으로 해석하지 않습니다. timeout 계열의 0과 양수 판정은 다른 jiffies 대기와 동일하게 확인합니다.',
 [('wait_event_idle의 대기 명령은 무엇인가요?', '공통 반복문의 schedule입니다.', 'task를 계속 실행시키는 busy loop입니다.', '매크로는 TASK_IDLE과 schedule을 전달합니다. load에 기여하지 않는 state와 CPU를 계속 소비하는 동작은 다릅니다.'),
  ('idle_timeout의 0 반환은 무엇을 뜻하나요?', '조건이 충족되지 않은 시간 만료입니다.', '반드시 TASK_RUNNING 성공입니다.', 'idle timeout도 ___wait_cond_timeout을 사용합니다. task state 선택과 잔여 시간 반환 계약을 구별하세요.')]),
('Waitqueue killable·TASK_WAKEKILL과 지정 state', 'include/linux/wait.h', 'wait_event_killable',
 'killable 대기는 TASK_KILLABLE을 공통 매크로에 전달하고, killable_timeout은 시간 제한 계약을 더합니다. 원문은 kill signal에 의한 중단을 명시합니다. wait_event_state는 호출자가 지정한 state를 사용하고 그 state가 허용할 때 signal 오류를 전달합니다. ___wait_is_interruptible은 컴파일 시간 상수이면 INTERRUPTIBLE 또는 WAKEKILL 비트를 검사하고, 상수로 판정할 수 없으면 준비 함수의 오류를 검사할 수 있도록 true가 됩니다.',
 '일반 signal과 killable 중단을 구별하세요. 임의 state 인자를 줄 때는 해당 task 상태와 signal_pending_state의 계약을 확인합니다. ___wait_is_interruptible의 true는 실제 signal이 있다는 뜻이 아니라 오류 분기를 검사할 필요가 있다는 뜻입니다.',
 [('___wait_is_interruptible이 true이면 실제 signal이 도착했다는 뜻인가요?', '아닙니다. 해당 오류 검사를 허용하는 판정입니다.', '맞습니다. signal 큐가 비어 있지 않다는 증거입니다.', '이 매크로는 state의 상수 여부와 비트를 검사합니다. 실제 signal 여부는 prepare_to_wait_event가 별도로 판정합니다.'),
  ('wait_event_state는 state를 어떻게 선택하나요?', '호출자가 전달한 state를 사용합니다.', '항상 TASK_INTERRUPTIBLE로 강제합니다.', 'wrapper는 공통 매크로에 지정 state를 전달합니다. state별 허용 signal과 대기 계약을 호출자가 확인해야 합니다.')])
])

ROWS.extend([
('Waitqueue 고해상도 timeout·타이머 task와 -ETIME', 'include/linux/wait.h', '__wait_event_hrtimeout',
 '고해상도 내부 대기는 스택 hrtimer_sleeper를 CLOCK_MONOTONIC의 상대 모드로 초기화합니다. timeout이 KTIME_MAX가 아니면 만료 시간과 current의 timer slack을 설정하고 타이머를 시작합니다. 공통 대기 명령은 sleeper의 task가 NULL이면 만료로 보고 -ETIME을 설정하여 끝냅니다. 조건 검사는 이 명령보다 먼저 수행됩니다. 종료 뒤에는 타이머 취소와 스택 타이머 정리를 수행합니다.',
 'ktime_t 시간 계약과 jiffies timeout 계약을 구별하세요. 반환값은 잔여 jiffies가 아닙니다. 스택 타이머가 task나 콜백에 남지 않도록 취소와 정리 경로를 따라갑니다. KTIME_MAX 분기는 타이머 시작을 생략하지만 초기화와 정리까지 생략하는 것은 아닙니다.',
 [('고해상도 시간 만료 코드는 무엇인가요?', '-ETIME입니다.', '항상 jiffies timeout의 0입니다.', '내부 명령은 sleeper task가 없을 때 -ETIME을 설정합니다. 일반 시간 제한 대기의 0·양수 계약과 다릅니다.'),
  ('KTIME_MAX이면 타이머 객체 초기화도 생략하나요?', '아닙니다. 만료 설정과 시작만 건너뜁니다.', '맞습니다. 전체 객체를 사용하지 않습니다.', '초기화는 분기 전에 있고 취소와 정리는 공통 종료 경로에 있습니다. 특정 분기가 생략하는 동작의 범위를 직접 읽으세요.')]),
('Waitqueue 고해상도 wrapper·조건 성공과 signal 상태', 'include/linux/wait.h', 'wait_event_hrtimeout',
 'wait_event_hrtimeout은 TASK_UNINTERRUPTIBLE을 사용하며 조건 성공에 0, 시간 만료에 -ETIME을 반환합니다. interruptible_hrtimeout은 TASK_INTERRUPTIBLE을 사용하고 허용 signal에는 -ERESTARTSYS도 반환할 수 있습니다. 일반 hrtimeout의 문서에 signal 표현이 보이더라도 실제 state 인자를 함께 확인해야 합니다. 바깥 조건이 이미 true이면 스택 타이머를 만들지 않고 성공할 수 있습니다.',
 'API 이름과 원문 state 선택, 실제 오류 경로를 함께 읽습니다. 성공 0을 일반 jiffies timeout의 실패 0과 혼동하지 마세요. 고해상도 대기의 정확한 타이머 동작은 hrtimer 구현과 별도 실행 검증에서 확인해야 합니다.',
 [('hrtimeout의 조건 성공 반환값 0은 실패인가요?', '아닙니다. 이 API에서는 조건 성공입니다.', '맞습니다. 모든 timeout API의 0은 실패입니다.', '고해상도 wrapper는 0 성공과 -ETIME 만료를 사용합니다. jiffies 시간 제한 API의 반환 계약과 구분해야 합니다.'),
  ('일반 hrtimeout wrapper가 전달하는 state는 무엇인가요?', 'TASK_UNINTERRUPTIBLE입니다.', '항상 TASK_INTERRUPTIBLE입니다.', '실제 내부 호출의 state 인자를 확인하세요. 문서의 포괄적 표현만으로 signal 중단 여부를 판단하지 마세요.')]),
('Waitqueue locked macro·조건 검사와 잠금 유지', 'include/linux/wait.h', '__wait_event_interruptible_locked',
 'locked 공통 매크로는 DEFINE_WAIT로 항목을 만들고 필요하면 EXCLUSIVE를 설정합니다. do_wait_intr 또는 IRQ 변형을 호출하고 오류가 없으면 잠금 아래 조건을 검사하는 반복을 수행합니다. 종료 뒤에는 등록 항목을 직접 제거하고 TASK_RUNNING을 복구합니다. 바깥 wrapper는 초기 조건도 이미 보유한 head 잠금 아래 검사합니다. 매크로를 떠날 때에도 그 잠금은 유지되어야 합니다.',
 'wq.lock을 잡고 진입하며 밖에서 사용하는 spin_lock 또는 spin_lock_irq 방식과 변형을 맞추세요. 조건을 바꾼 쪽도 해당 잠금 규약과 wake_up_locked를 지킵니다. 성공과 signal 오류 모두의 항목 정리와 잠금 상태를 확인합니다.',
 [('locked 대기 매크로를 떠날 때 head 잠금은 어떤 상태인가요?', '호출자가 계속 보유한 상태입니다.', '항상 풀린 상태입니다.', 'do_wait_intr는 정상 경로에서 재획득하고 signal 경로에서는 유지합니다. 공통 매크로의 정리는 그 잠금 아래 수행됩니다.'),
  ('이 계열의 condition 검사는 어디에서 하나요?', 'head 잠금이 잡힌 구간에서 합니다.', '잠금을 풀고 schedule하는 동안만 합니다.', '원문 문서는 조건 검사와 진입·종료의 잠금 보유를 명시합니다. 수면 중 해제와 조건 검사 중 보유를 구별하세요.')]),
('Waitqueue 별도 lock_irq·cmd와 수면 사이의 해제', 'include/linux/wait.h', '__wait_event_lock_irq',
 'lock_irq 계열은 대기열 head 자체와 별개로 전달한 lock을 조건 보호에 사용합니다. 공통 대기 명령은 spin_unlock_irq, 선택 cmd, schedule, spin_lock_irq 순서입니다. 대기열 항목의 준비는 공통 대기 프로토콜로 수행하며 조건 검사는 전달한 lock을 보유한 상태에서 합니다. interruptible 변형은 같은 해제·재획득 구조에 signal 오류를 결합합니다. locked 계열의 head 잠금과 혼동하면 안 됩니다.',
 '지정 lock과 IRQ 비활성 상태를 가진 계약으로 진입하고, 매크로 밖의 잠금 방식도 맞추세요. cmd는 전달 lock이 풀린 구간에서 실행됩니다. 대기열 잠금과 조건 데이터 잠금의 순서가 충돌하지 않도록 호출 관계를 확인합니다.',
 [('lock_irq_cmd의 cmd는 전달 lock 안에서 실행되나요?', '아닙니다. 잠금을 푼 뒤 실행합니다.', '맞습니다. schedule 후 재획득한 뒤 실행합니다.', '공통 명령은 unlock, cmd, schedule, lock 순서입니다. 사용자 명령이 어느 보호 구간에서 실행되는지 중요합니다.'),
  ('전달 lock은 항상 대기열의 wq.lock과 같은 객체인가요?', '아닙니다. 별도 조건 보호 잠금일 수 있습니다.', '맞습니다. 인자는 무시하고 wq.lock만 씁니다.', '매크로는 인자로 받은 lock을 해제하고 재획득합니다. 대기열 준비의 내부 잠금과 조건 보호 잠금을 구별하세요.')]),
('Waitqueue lock_irq timeout·잠금과 세 가지 반환', 'include/linux/wait.h', '__wait_event_lock_irq_timeout',
 'lock_irq timeout의 실제 수면 명령은 전달 lock의 IRQ 잠금을 풀고 schedule_timeout의 반환값으로 __ret를 갱신한 뒤 다시 잠금을 잡습니다. 바깥 timeout 조건 helper는 이미 충족된 조건과 0 만료를 먼저 판정합니다. uninterruptible과 interruptible wrapper는 state를 다르게 전달하며, interruptible은 signal 오류를 반환할 수 있습니다. 초기 즉시 반환에서도 호출 전 잠금 보유 계약은 유지됩니다.',
 '양수 조건 성공, 0 만료와 음수 signal 오류를 구별합니다. 값 1에는 만료 경계 성공도 포함될 수 있습니다. 실제 대기 여부와 관계없이 진입·종료의 lock_irq 계약을 확인하고 이전 IRQ 상태를 저장·복원하는 API로 오해하지 마세요.',
 [('실제 timeout 수면 중 전달 lock은 풀리나요?', '그렇습니다. 돌아온 뒤 다시 잡습니다.', '아닙니다. timer 만료까지 보유합니다.', '내부 cmd는 spin_unlock_irq, schedule_timeout, spin_lock_irq 순서입니다. 시간 제한은 잠금 보유 수면을 허용하는 기능이 아닙니다.'),
  ('초기 조건이 true인 경로는 lock을 반드시 한 번 해제하나요?', '아닙니다. 내부 대기를 건너뛸 수 있습니다.', '맞습니다. 즉시 반환도 항상 unlock합니다.', '바깥 timeout 조건 검사에서 끝나면 수면 cmd가 실행되지 않습니다. 경로별 잠금 동작과 최종 보유 상태를 구분해야 합니다.')]),
('Waitqueue 내부 exclusive helper·앞쪽과 tail의 차이', 'include/linux/wait.h', '__add_wait_queue_exclusive',
 '내부 __add_wait_queue_exclusive는 EXCLUSIVE를 추가하고 __add_wait_queue를 호출하므로 priority 앞부분 뒤에 삽입합니다. __add_wait_queue_entry_tail_exclusive는 EXCLUSIVE를 추가한 뒤 tail helper를 호출합니다. 외부 add_wait_queue_exclusive의 tail 동작을 모든 exclusive 이름의 helper로 일반화하면 안 됩니다. __remove_wait_queue는 리스트 링크를 삭제하며 list_del_init처럼 자기 참조를 복구하지 않습니다.',
 '내부 helper는 이미 적절한 잠금이 보유된 문맥에서 사용하세요. 링크 삭제 뒤 재사용할 항목은 다음 API가 기대하는 초기 상태를 따로 확인합니다. 비슷한 이름도 삽입 위치와 삭제 후 링크 상태를 각각 대조합니다.',
 [('내부 __add_wait_queue_exclusive는 항상 tail에 삽입하나요?', '아닙니다. __add_wait_queue의 앞쪽 규칙을 씁니다.', '맞습니다. exclusive라는 이름이면 모두 tail입니다.', '원문 호출 대상이 front helper인지 tail helper인지 확인하세요. 외부 API와 내부 helper의 등록 위치는 다를 수 있습니다.'),
  ('__remove_wait_queue가 자기 참조 링크를 복구하나요?', '아닙니다. list_del을 사용합니다.', '맞습니다. 언제나 list_del_init입니다.', '본문의 삭제 helper를 확인하면 차이가 있습니다. 제거된 항목에 list_empty를 다시 쓰려면 링크 초기 상태의 계약을 지켜야 합니다.')]),
('Waitqueue init_wait_entry·current와 autoremove 연결', 'kernel/sched/wait.c', 'init_wait_entry',
 'init_wait_entry는 지정 flags를 저장하고 private를 current로, func를 autoremove_wake_function으로 설정하며 entry를 자기 참조로 초기화합니다. 이는 공통 대기 매크로의 스택 항목을 준비하는 방식입니다. init_waitqueue_func_entry는 사용자 func와 NULL private를 설정하지만 링크 초기화는 하지 않습니다. 함수별 설정 필드의 차이를 알고 사용해야 초기화 누락이나 잘못된 콜백 문맥을 피할 수 있습니다.',
 '공통 대기의 current와 autoremove 계약을 연결해 읽습니다. 사용자 콜백 항목은 private와 리스트 초기화를 필요한 규약대로 추가하세요. 함수를 호출한 뒤 flag, private, func와 두 링크의 값을 직접 표시해 보세요.',
 [('init_wait_entry의 기본 깨움 콜백은 무엇인가요?', 'autoremove_wake_function입니다.', '항상 사용자 제공 NULL 콜백입니다.', '함수는 current와 autoremove 콜백을 직접 설정합니다. 공통 매크로의 항목 정리 동작이 이 초기화와 연결됩니다.'),
  ('init_waitqueue_func_entry만 호출해도 링크가 자기 참조인가요?', '아닙니다. 링크 초기화는 별도로 필요합니다.', '맞습니다. init_wait_entry와 모든 필드가 같습니다.', '사용자 func 초기화 함수는 flags, private, func만 씁니다. 함수 이름의 유사성보다 실제 설정 필드를 확인하세요.')]),
('Waitqueue 헤더 끝·init_wait와 callback 선언', 'include/linux/wait.h', 'init_wait',
 '헤더 끝의 init_wait 매크로는 current, autoremove 콜백, 자기 참조 링크와 flags 0을 설정합니다. 그 뒤의 task_call_f는 콜백 타입 선언입니다. wait.h는 default_wake_function과 task_call_func의 선언도 노출하지만 본체를 이 헤더에 구현하지 않습니다. task_call_f는 task 포인터와 void 문맥을 받아 int를 반환하는 콜백 타입입니다. 헤더를 읽어 알 수 있는 것은 호출 형태이며, 실제 task 잠금·실행 문맥·반환 의미는 구현과 호출자가 정하는 계약에서 확인해야 합니다. 선언을 본체로 오해하여 알고리즘을 추측하지 마세요.',
 'C의 typedef 함수 포인터, 함수 선언과 함수 정의를 구별하는 연습으로 사용하세요. 기본 깨움이 실제 task를 처리하는 부분은 scheduler 원문과 연결해 읽습니다. task_call_func의 안전 조건을 이 선언만 보고 단정하지 않습니다.',
 [('task_call_f 선언만으로 callback이 어떤 잠금 아래 실행되는지 알 수 있나요?', '아닙니다. 구현과 호출 계약을 확인해야 합니다.', '맞습니다. int 반환이 모든 잠금을 보장합니다.', '함수 포인터 타입은 인자와 반환 자료형을 정의합니다. 실행 문맥이나 동기화 보장은 별도 구현과 문서의 계약입니다.'),
  ('헤더의 default_wake_function 선언이 함수 본체인가요?', '아닙니다. 다른 소스의 정의와 연결됩니다.', '맞습니다. 세미콜론 선언이 전체 알고리즘입니다.', 'C의 함수 선언과 중괄호 본체를 가진 정의를 구별하세요. 호출 형태와 실제 동작의 근거는 서로 다른 위치에 있을 수 있습니다.')])
])

ROWS.append((
 'Waitqueue flags·표시 비트 정의와 콜백 전 snapshot', 'include/linux/wait.h', 'wait_queue_entry',
 '헤더는 EXCLUSIVE, WOKEN, CUSTOM, DONE, PRIORITY를 각각 다른 비트 값으로 정의합니다. 선언된 비트가 모두 공통 깨움 함수의 필터는 아닙니다. 공통 순회는 콜백 전 flags를 지역 변수로 읽고 그 snapshot의 EXCLUSIVE로 예산 소비를 결정합니다. PRIORITY는 등록 위치에, WOKEN은 별도 woken 프로토콜에 사용합니다. CUSTOM과 DONE의 개별 의미는 이 파일의 일반 순회가 자동으로 구현하지 않습니다.',
 'flag 선언, 실제로 읽는 함수와 사용자 콜백 규약을 구별하세요. 콜백이 실행 중 EXCLUSIVE를 바꾸면 같은 호출의 예산 판단은 이미 읽은 값에 근거합니다. 사용자 표시 비트를 설정했다는 사실만으로 공통 순회가 task를 건너뛴다고 가정하지 마세요.',
 [('공통 깨움 순회가 사용하는 EXCLUSIVE 값은 언제 읽나요?', '해당 항목의 콜백 호출 전에 읽습니다.', '항상 콜백이 끝난 뒤 다시 읽습니다.', '원문은 unsigned flags = curr->flags를 콜백 전에 수행합니다. 이후 예산 판정은 그 지역 snapshot을 사용합니다.'),
  ('DONE 비트를 설정하면 공통 순회가 반드시 항목을 건너뛰나요?', '아닙니다. 일반 순회에는 그 비트의 자동 필터가 없습니다.', '맞습니다. 모든 선언된 비트는 공통 필터입니다.', '비트 정의와 사용 구현은 다른 위치입니다. 이 함수는 콜백 결과와 EXCLUSIVE를 판정하며 DONE 자동 제외를 수행하지 않습니다.')]))

def register(topic, q, detail):
    for title, path, symbol, principle, use, qa in ROWS:
        topic(title, '동기화', path, symbol,
              '실제 Linux 대기열의 구조와 등록·조건 검사·깨움·정리 순서를 읽어 잠드는 기술의 사용 조건을 배웁니다.',
              principle, use,
              '리스트 등록, task 상태, 조건 값과 콜백 반환값을 따로 표시하며 해당 원문의 호출 흐름을 추적하세요.',
              *(q(*x) for x in qa), details=[
                  detail('원문 확인', '고정한 Linux v6.12의 wait.h와 kernel/sched/wait.c를 전체 읽고 해당 정의와 호출 관계를 대조했습니다.'),
                  detail('검증 범위', '전체 헤더와 원문 C 함수를 명시적 리스트·잠금·task·스케줄러 직렬 모델에 연결했습니다. 선택한 등록·깨움·정리·signal·timeout 사례 40,004건을 최적화 및 ASan·UBSan 구성에서 각각 검사했습니다. 모든 매크로 변형이나 실제 커널 동시성을 실행한 증거는 아닙니다.')])
